import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.ReceiveMessageRequest;
import software.amazon.awssdk.services.sqs.model.Message;
import java.util.List;

@WebServlet("/messages")
public class MessageDashboardServlet extends HttpServlet {

    private static final ConcurrentLinkedQueue<String> messageBuffer = new ConcurrentLinkedQueue<>();
    private static final AtomicBoolean consumerRunning = new AtomicBoolean(false);
    private static volatile boolean shutdownRequested = false;
    private static Thread consumerThread;

    // Signal-like shutdown hook that races with message processing
    static {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            shutdownRequested = true;
            // Race condition: consumer may still be writing to buffer
            // during shutdown, causing partial/corrupted messages
            if (consumerThread != null) {
                consumerThread.interrupt();
                // Don't wait - this creates the race window
            }
        }));
    }

    @Override
    public void init() {
        startConsumer();
    }

    private void startConsumer() {
        if (consumerRunning.compareAndSet(false, true)) {
            consumerThread = new Thread(() -> {
                SqsClient sqs = SqsClient.create();
                String queueUrl = System.getenv("SQS_QUEUE_URL");
                while (!shutdownRequested) {
                    try {
                        ReceiveMessageRequest req = ReceiveMessageRequest.builder()
                            .queueUrl(queueUrl)
                            .maxNumberOfMessages(10)
                            .waitTimeSeconds(5)
                            .build();
                        List<Message> messages = sqs.receiveMessage(req).messages();
                        for (Message msg : messages) {
                            // Race: shutdown hook may fire here, corrupting state
                            // Message body is stored raw - may contain user HTML/JS
                            String body = msg.body();
                            messageBuffer.offer(body);
                            // Keep buffer bounded
                            while (messageBuffer.size() > 100) {
                                messageBuffer.poll();
                            }
                        }
                    } catch (Exception e) {
                        if (!shutdownRequested) {
                            try { Thread.sleep(1000); } catch (InterruptedException ie) { break; }
                        }
                    }
                }
                consumerRunning.set(false);
            });
            consumerThread.setDaemon(true);
            consumerThread.start();
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.setContentType("text/html; charset=UTF-8");
        PrintWriter out = resp.getWriter();

        // Build dashboard HTML with raw message content
        out.println("<!DOCTYPE html><html><head><title>Message Queue Dashboard</title>");
        out.println("<style>body{font-family:monospace;} .msg{border:1px solid #ccc;padding:8px;margin:4px;}</style>");
        out.println("</head><body>");
        out.println("<h1>SQS Message Buffer (" + messageBuffer.size() + " messages)</h1>");
        out.println("<div id='messages'>");

        // XSS vulnerability: message bodies rendered without escaping
        // The race condition means partial messages could also appear
        for (String message : messageBuffer) {
            out.println("<div class='msg'>" + message + "</div>");
        }

        out.println("</div>");
        out.println("<script>setTimeout(function(){location.reload();}, 5000);</script>");
        out.println("</body></html>");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        // Manual message injection for testing - also unescaped
        String testMsg = req.getParameter("msg");
        if (testMsg != null && !testMsg.isEmpty()) {
            messageBuffer.offer(testMsg);
        }
        resp.sendRedirect("/messages");
    }
}
